"""Vampire number hunter: enumerate vampires and their fangs up to a bound."""
from __future__ import annotations


def digits(n: int) -> list[int]:
    return sorted(int(c) for c in str(n))


def num_digits(n: int) -> int:
    return len(str(n))


def is_vampire_pair(v: int, x: int, y: int) -> bool:
    k, r = divmod(num_digits(v), 2)
    if r != 0 or num_digits(x) != k or num_digits(y) != k:
        return False
    if x % 10 == 0 and y % 10 == 0:
        return False
    return x * y == v and sorted(digits(x) + digits(y)) == digits(v)


def vampires_up_to(limit: int) -> list[tuple[int, list[tuple[int, int]]]]:
    out: list[tuple[int, list[tuple[int, int]]]] = []
    for v in range(1, limit):
        if num_digits(v) % 2:
            continue
        pairs = []
        x = 1
        while x * x <= v:
            if v % x == 0 and is_vampire_pair(v, x, v // x):
                pairs.append((x, v // x))
            x += 1
        if pairs:
            out.append((v, pairs))
    return out


if __name__ == "__main__":
    for v, pairs in vampires_up_to(10000):
        print(v, "=", ", ".join(f"{x}x{y}" for x, y in pairs))

"""Verify the three factoring-free obstructions on every vampire pair."""
from __future__ import annotations


def num_digits(n: int) -> int:
    return len(str(n))


def obstruction_report(x: int, y: int) -> dict[str, bool]:
    return {
        "casting_out_nines": (x * y) % 9 == (x + y) % 9
        and ((x - 1) * (y - 1)) % 9 == 1,
        "mod_three_sieve": x % 3 != 1 and y % 3 != 1,
        "length_additive": num_digits(x * y) == num_digits(x) + num_digits(y),
    }


if __name__ == "__main__":
    for (x, y) in [(21, 60), (15, 93), (35, 41), (30, 51), (27, 81)]:
        print(f"{x}x{y}={x*y}:", obstruction_report(x, y))

"""Base-2 bridge: submultiplicativity of the binary digit sum s2."""
from __future__ import annotations


def s2(n: int) -> int:
    return bin(n).count("1")


def bound(x: int, y: int) -> int:
    return min(y * s2(x), x * s2(y))


def demonstrate(x: int, y: int) -> None:
    v = x * y
    print(f"s2({v}) = {s2(v)} <= min({y}*{s2(x)}, {x}*{s2(y)}) = {bound(x, y)}"
          f"  -> {s2(v) <= bound(x, y)}")


if __name__ == "__main__":
    for (x, y) in [(21, 60), (15, 93), (35, 41), (999, 7)]:
        demonstrate(x, y)

