def num_digits(n: int) -> int:
    return len(str(n))


def digit_multiset(n: int) -> list[int]:
    return sorted(int(c) for c in str(n))


def vampire_pairs(v: int) -> list[tuple[int, int]]:
    """Return all vampire fang pairs (x, y), x <= y, of v via divisor scan."""
    if num_digits(v) % 2:
        return []
    k = num_digits(v) // 2
    pairs: list[tuple[int, int]] = []
    x = 1
    while x * x <= v:
        if v % x == 0:
            y = v // x
            if (num_digits(x) == k and num_digits(y) == k
                    and not (x % 10 == 0 and y % 10 == 0)
                    and sorted(digit_multiset(x) + digit_multiset(y))
                    == digit_multiset(v)):
                pairs.append((x, y))
        x += 1
    return pairs

from __future__ import annotations


def num_digits(n: int) -> int:
    return len(str(n))


def survives_sieves(x: int, y: int) -> bool:
    """Cheap factoring-free rejection tests for a candidate fang pair.

    Returns False as soon as any structural obstruction is violated.
    """
    # Casting out nines and its corollary.
    if (x * y) % 9 != (x + y) % 9:
        return False
    if ((x - 1) * (y - 1)) % 9 != 1 % 9:
        return False
    # Mod-three fang sieve.
    if x % 3 == 1 or y % 3 == 1:
        return False
    # No carry shrinkage.
    if num_digits(x * y) != num_digits(x) + num_digits(y):
        return False
    return True

